"""
Ghidra SRE Script: Export C Header
==================================
Exports recovered function prototypes, type definitions, and calling conventions
to a clean ANSI C header file (.h).
"""

def run_script(orch, binary_path):
    report = orch.analyze_binary(binary_path)
    header_lines = [
        "/* Generated by NSA Ghidra Autonomous SRE Suite */",
        f"/* Target: {report.metadata.file_name} ({report.metadata.architecture}) */",
        "",
        "#ifndef _GHIDRA_EXPORTED_TYPES_H",
        "#define _GHIDRA_EXPORTED_TYPES_H",
        "",
        "#include <stdint.h>",
        "#include <stdbool.h>",
        "",
        "typedef uint64_t undefined8;",
        "typedef uint32_t undefined4;",
        "typedef uint16_t undefined2;",
        "typedef uint8_t  undefined1;",
        ""
    ]
    for fn in report.functions:
        params = ", ".join(fn.parameters) if fn.parameters else "void"
        header_lines.append(f"{fn.return_type} {fn.calling_convention} {fn.name}({params});")

    header_lines.append("")
    header_lines.append("#endif /* _GHIDRA_EXPORTED_TYPES_H */")
    header_content = "\n".join(header_lines)

    return {
        "script": "export_ghidra_c_header.py",
        "total_functions_exported": len(report.functions),
        "header_content": header_content
    }

if __name__ == "__main__":
    import sys
    from ghidra_orchestrator import GhidraOrchestrator
    target = sys.argv[1] if len(sys.argv) > 1 else "ghidra/samples/vulnerable_service.exe"
    res = run_script(GhidraOrchestrator(), target)
    print(res["header_content"])
